239	        this.audit = audit;
240	    }
241	
242	    /** The sheet's settings now. */
243	    @Transactional
244	    public Sheet settings(String sheetId, String user) {
245	        return sheets.load(sheetId, user);
246	    }
247	
248	    /**
249	     * Save the settings given: {@code setClerkLimit} the clerk limit (null: no limit), a non-null
250	     * {@code floor} the floor, a non-null {@code terms} the terms in days; each one saved is audited, even when its value is the same. A floor
251	     * that moves live dues records the rollups that moved.
252	     */
253	    @Transactional
254	    public Sheet save(String sheetId, String user, boolean setClerkLimit, BigDecimal clerkLimit, BigDecimal floor,
255	            Integer terms) {
256	        Sheet sheet = sheets.lock(sheetId, user);
257	        if (setClerkLimit) {
258	            sheet.setClerkLimit(clerkLimit);
259	            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
260	                    + " key=clerk-limit value=" + (clerkLimit == null ? "" : clerkLimit.toPlainString()));
261	        }
262	        if (floor != null) {
263	            RollupService.Rollup before = rollups.snapshot(sheetId);
264	            sheet.setFloor(floor);
265	            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
266	                    + " key=floor value=" + floor.toPlainString());
267	            rollups.recordChanges(sheetId, user, before);
268	        }
269	        if (terms != null) {
270	            sheet.setTerms(terms);
271	            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
272	                    + " key=terms value=" + terms);
273	        }
274	        return sheet;
275	    }
276	
277	    /** The roles the sheet gives user names, by name; a name not among them is a clerk. */
278	    @Transactional(readOnly = true)
279	    public List<SheetRole> roles(String sheetId) {
280	        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
281	    }
282	
283	    /** The role the sheet gives a user name; clerk when it gives none. */
284	    @Transactional(readOnly = true)
285	    public Role roleOf(String sheetId, String userName) {
286	        return roles.findBySheetIdAndUserName(sheetId, userName).map(SheetRole::getRole).orElse(Role.CLERK);
287	    }
288	
289	    /** Give a user name a role, replacing the one it had. */
290	    @Transactional
291	    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
292	        sheets.lock(sheetId, user);
293	        SheetRole entry = roles.findBySheetIdAndUserName(sheetId, userName)
294	                .orElseGet(() -> new SheetRole(sheetId, userName, role));
295	        entry.setRole(role);
296	        SheetRole saved = roles.saveAndFlush(entry);
297	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
298	                + " user=" + userName + " role=" + role.name().toLowerCase());
299	        return saved;
300	    }
301	}
