417	package net.officefloor.hq.app.rollup;
418	
419	import java.math.BigDecimal;
420	import java.math.RoundingMode;
421	import java.time.LocalDate;
422	import java.util.ArrayList;
423	import java.util.LinkedHashMap;
424	import java.util.List;
425	import java.util.Map;
426	import java.util.Objects;
427	import java.util.stream.Collectors;
428	import net.officefloor.hq.app.Audit;
429	import net.officefloor.hq.app.claim.Claim;
430	import net.officefloor.hq.app.claim.ClaimRepository;
431	import net.officefloor.hq.app.claim.ClaimStatus;
432	import net.officefloor.hq.app.person.Person;
433	import net.officefloor.hq.app.person.PersonRepository;
434	import net.officefloor.hq.app.rate.Rate;
435	import net.officefloor.hq.app.rate.RateRepository;
436	import net.officefloor.hq.app.sheet.Sheet;
437	import net.officefloor.hq.app.sheet.SheetRepository;
438	import org.springframework.stereotype.Service;
439	import org.springframework.transaction.annotation.Transactional;
440	
441	/**
442	 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
443	 * claimed-total and due-total. A change takes a snapshot before it and, once its own audit lines are
444	 * written, records a ROLLUP line per person whose figures moved and a TOTALS line when the totals did.
445	 */
446	@Service
447	public class RollupService {
448	
449	    /** A person's figures, as text with two decimals; the due-total is "n/a" when they have none. */
450	    public record Figures(String name, String claimed, String dueTotal) {}
451	
452	    /** Each person's figures by id, in the order they were added, and the sheet's totals. */
453	    public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}
454	
455	    private final PersonRepository people;
456	    private final ClaimRepository claims;
457	    private final RateRepository rates;
458	    private final SheetRepository sheets;
459	    private final Audit audit;
460	
461	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
462	            SheetRepository sheets, Audit audit) {
463	        this.people = people;
464	        this.claims = claims;
465	        this.rates = rates;
466	        this.sheets = sheets;
467	        this.audit = audit;
468	    }
469	
470	    /**
471	     * The sheet's figures now. Only open and settled claims count (a held person's open ones do not); a person's due-total is the sum of
472	     * their figures (those with one), n/a when their grade has no rate in force on the sheet's today
473	     * and no counting claim of theirs keeps a fixed (settled or stated) figure.
474	     */
475	    @Transactional(readOnly = true)
476	    public Rollup snapshot(String sheetId) {
477	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElseGet(LocalDate::now);
478	        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
479	                .filter(c -> c.getStatus().counts())
480	                .collect(Collectors.groupingBy(Claim::getPersonId));
481	        Map<Long, Figures> out = new LinkedHashMap<>();
482	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
483	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
484	        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
485	            List<Claim> counted = byPerson.getOrDefault(p.getId(), List.of()).stream()
486	                    .filter(c -> counts(p, c))
487	                    .toList();
488	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
489	            BigDecimal due = BigDecimal.ZERO.setScale(2);
490	            for (Claim c : counted) {
491	                claimed = claimed.add(c.getAmount());
492	                BigDecimal figure = figure(sheetId, p, c);
493	                if (figure != null) due = due.add(figure);
494	            }
495	            boolean rated = rates.findInForce(sheetId, p.getGrade(), today).isPresent();
496	            boolean anyFixed = counted.stream().anyMatch(Claim::keepsFigure);
497	            claimedTotal = claimedTotal.add(claimed);
498	            if (rated || anyFixed) dueTotal = dueTotal.add(due);
499	            out.put(p.getId(), new Figures(p.getName(), text(claimed), rated || anyFixed ? text(due) : "n/a"));
500	        }
501	        return new Rollup(out, text(claimedTotal), text(dueTotal));
502	    }
503	
504	    /**
505	     * Whether a claim counts in the live totals: open and settled claims do, except the open claims
506	     * of a person on hold.
507	     */
508	    public static boolean counts(Person person, Claim claim) {
509	        return claim.getStatus().counts() && !(person.isHeld() && claim.getStatus() == ClaimStatus.OPEN);
510	    }
511	
512	    /**
513	     * Record, once the change commits, a ROLLUP line for each person whose figures moved since
514	     * {@code before} (a person who did not exist then counts as moved), then a TOTALS line when the
515	     * sheet's totals moved.
516	     */
517	    @Transactional(readOnly = true)
518	    public void recordChanges(String sheetId, String user, Rollup before) {
519	        Rollup after = snapshot(sheetId);
520	        List<String> lines = new ArrayList<>();
521	        after.people().forEach((id, now) -> {
522	            Figures was = before.people().get(id);
523	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
524	                lines.add("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
525	                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal());
526	            }
527	        });
528	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
529	                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
530	            lines.add("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
531	                    + " due-total=" + after.dueTotal());
532	        }
533	        lines.forEach(audit::recordOnCommit);
534	    }
535	
536	    /**
537	     * The figure a claim shows: a settled claim's fixed due, else the figure its person's last
538	     * statement bound it to, else its amount times the rate in force on its date, raised to the
539	     * sheet's floor; null when none.
540	     */
541	    @Transactional(readOnly = true)
542	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
543	        if (claim.getDue() != null) return claim.getDue();
544	        if (claim.isStated()) return claim.getStatedDue();
545	        BigDecimal floor = sheets.findById(sheetId).map(Sheet::getFloor).orElse(BigDecimal.ZERO);
546	        return rates.findInForce(sheetId, person.getGrade(), claim.getDate())
547	                .map(rate -> due(claim.getAmount(), rate).max(floor).setScale(2))
548	                .orElse(null);
549	    }
550	
551	    /** The amount times the rate's percent, rounded half to even to cents (as the screen works it out). */
552	    private static BigDecimal due(BigDecimal amount, Rate rate) {
553	        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
554	    }
555	
556	    private static String text(BigDecimal amount) {
557	        return amount.setScale(2).toPlainString();
558	    }
559	}
