688	import java.math.BigDecimal;
689	import java.time.LocalDate;
690	import java.util.List;
691	import net.officefloor.hq.app.Audit;
692	import net.officefloor.hq.app.person.Person;
693	import net.officefloor.hq.app.person.PersonRepository;
694	import net.officefloor.hq.app.person.Statement;
695	import net.officefloor.hq.app.person.StatementRepository;
696	import net.officefloor.hq.app.period.PeriodService;
697	import net.officefloor.hq.app.rate.RateRepository;
698	import net.officefloor.hq.app.rollup.RollupService;
699	import net.officefloor.hq.app.settings.Role;
700	import net.officefloor.hq.app.settings.SettingsService;
701	import net.officefloor.hq.app.sheet.Sheet;
702	import net.officefloor.hq.app.sheet.SheetService;
703	import org.springframework.http.HttpStatus;
704	import org.springframework.stereotype.Service;
705	import org.springframework.transaction.annotation.Transactional;
706	import org.springframework.web.server.ResponseStatusException;
707	
708	@Service
709	public class ClaimService {
710	
711	    private final ClaimRepository claims;
712	    private final PersonRepository people;
713	    private final RateRepository rates;
714	    private final StatementRepository statements;
715	    private final SheetService sheets;
716	    private final RollupService rollups;
717	    private final PeriodService periods;
718	    private final SettingsService settings;
719	    private final Audit audit;
720	
721	    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates,
722	            StatementRepository statements, SheetService sheets, RollupService rollups, PeriodService periods,
723	            SettingsService settings, Audit audit) {
724	        this.periods = periods;
725	        this.settings = settings;
726	        this.claims = claims;
727	        this.people = people;
728	        this.rates = rates;
729	        this.statements = statements;
730	        this.sheets = sheets;
731	        this.rollups = rollups;
732	        this.audit = audit;
733	    }
734	
735	    /** The sheet's claims, newest first. */
736	    @Transactional(readOnly = true)
737	    public List<Claim> list(String sheetId) {
738	        return claims.findBySheetIdOrderByIdDesc(sheetId);
739	    }
740	
741	    /**
742	     * Add a claim for a person; without a date it is dated the sheet's today. One dated in a closed
743	     * period is refused.
744	     */
745	    @Transactional
746	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
747	        sheets.lock(sheetId, user);
748	        Person person = people.findByIdAndSheetId(personId, sheetId)
749	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
750	        LocalDate dated = dateOrToday(sheetId, date);
751	        periods.requireOpenOn(sheetId, dated);
752	        requireNotRetired(person, dated);
753	        RollupService.Rollup before = rollups.snapshot(sheetId);
754	        Claim saved = claims.saveAndFlush(new Claim(sheetId, personId, amount, dated, noteOf(note)));
755	        audit(sheetId, user, "CLAIM_ADDED", person, saved, saved.getNumber());
756	        rollups.recordChanges(sheetId, user, before);
757	        return saved;
758	    }
759	
760	    /**
761	     * Change a draft claim's amount, date and note; without a date it is dated the sheet's today. A
762	     * claim that is no longer a draft is refused (an open one is voided and a new one added instead),
763	     * as is one dated in a closed period, or moved into one.
764	     */
765	    @Transactional
766	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note) {
767	        sheets.lock(sheetId, user);
768	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
769	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
770	        if (claim.getStatus() != ClaimStatus.DRAFT) {
771	            throw new ResponseStatusException(HttpStatus.CONFLICT,
772	                    "A " + claim.getStatus() + " claim cannot be edited");
773	        }
774	        LocalDate dated = dateOrToday(sheetId, date);
775	        periods.requireOpenOn(sheetId, claim.getDate());
776	        periods.requireOpenOn(sheetId, dated);
777	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
778	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
779	        requireNotRetired(owner, dated);
780	        RollupService.Rollup before = rollups.snapshot(sheetId);
781	        claim.setAmount(amount);
782	        claim.setDate(dated);
783	        claim.setNote(noteOf(note));
784	        Claim saved = claims.saveAndFlush(claim);
785	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
786	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
787	        audit(sheetId, user, "CLAIM_EDITED", person, saved, saved.getNumber());
788	        rollups.recordChanges(sheetId, user, before);
789	        return saved;
790	    }
791	
792	    /**
793	     * Move a claim to its next status; a change its current status does not allow is refused, as is
794	     * settling it by the user who opened it, settling it by a clerk when its due is above the sheet's
795	     * clerk limit (or it has none while there is a limit), and any change to a claim dated in a closed
796	     * period.
797	     */
798	    @Transactional
799	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
800	        Sheet sheet = sheets.lock(sheetId, user);
801	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
802	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
803	        periods.requireOpenOn(sheetId, claim.getDate());
804	        if (!claim.getStatus().canBecome(next)) {
805	            throw new ResponseStatusException(HttpStatus.CONFLICT,
806	                    "A " + claim.getStatus() + " claim cannot become " + next);
807	        }
808	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
809	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
810	        }
811	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
812	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
813	        if (next == ClaimStatus.SETTLED) {
814	            requireMaySettle(sheet, user, person, claim);
815	        }
816	        RollupService.Rollup before = rollups.snapshot(sheetId);
817	        Integer number = next == ClaimStatus.OPEN ? Integer.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
818	        claim.setStatus(next);
819	        claim.setNumber(number);
820	        if (next == ClaimStatus.OPEN) {
821	            claim.setOpenedBy(user);
822	        }
823	        if (next == ClaimStatus.SETTLED) {
824	            claim.setDue(figure(sheetId, person, claim));
825	        }
826	        Claim saved = claims.saveAndFlush(claim);
827	        String event = switch (next) {
828	            case OPEN -> "CLAIM_OPENED";
829	            case SETTLED -> "CLAIM_SETTLED";
830	            default -> "CLAIM_VOIDED";
831	        };
832	        String suffix = next == ClaimStatus.SETTLED
833	                ? " due=" + (saved.getDue() == null ? "n/a" : saved.getDue().setScale(2).toPlainString())
834	                : "";
835	        audit(sheetId, user, event, person, saved, number, suffix);
836	        rollups.recordChanges(sheetId, user, before);
837	        return saved;
838	    }
839	
840	    /**
841	     * Take a statement for a person on the sheet's today: their due-total then (the sum of the figures
842	     * of their claims that count, a held person's open ones not among them; n/a when their grade has
843	     * no rate in force today and none of those claims has a fixed or bound figure) is recorded, and each claim that counts is bound to its
844	     * figure then, the others left unbound. Their claims, newest first.
845	     */
846	    @Transactional
847	    public List<Claim> statement(String sheetId, String user, long personId) {
848	        Sheet sheet = sheets.lock(sheetId, user);
849	        Person person = people.findByIdAndSheetId(personId, sheetId)
850	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
851	        RollupService.Rollup before = rollups.snapshot(sheetId);
852	        List<Claim> theirs = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
853	                .filter(c -> c.getPersonId().equals(personId))
854	                .toList();
855	        List<Claim> counting = theirs.stream().filter(c -> RollupService.counts(person, c)).toList();
856	        boolean anyFixed = counting.stream().anyMatch(Claim::keepsFigure);
857	        boolean rated = rates.findInForce(sheetId, person.getGrade(), sheet.getToday()).isPresent();
858	        BigDecimal total = BigDecimal.ZERO.setScale(2);
859	        for (Claim c : theirs) {
860	            if (RollupService.counts(person, c)) {
861	                BigDecimal figure = figure(sheetId, person, c);
862	                if (figure != null) total = total.add(figure);
863	                c.bind(figure);
864	            } else {
865	                c.unbind();
866	            }
867	        }
868	        claims.saveAllAndFlush(theirs);
869	        BigDecimal dueTotal = rated || anyFixed ? total : null;
870	        statements.saveAndFlush(new Statement(sheetId, personId, sheet.getToday(), dueTotal, counting.size(), user));
871	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
872	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString())
873	                + " claims=" + counting.size());
874	        rollups.recordChanges(sheetId, user, before);
875	        return theirs;
876	    }
877	
878	    /** The figure a claim shows (see {@link RollupService#figure}); null when none. */
879	    private BigDecimal figure(String sheetId, Person person, Claim claim) {
880	        return rollups.figure(sheetId, person, claim);
881	    }
882	
883	    /**
884	     * Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd; a claim
885	     * with a number (a voided one keeps it) ends with it.
886	     */
887	    private void audit(String sheetId, String user, String event, Person person, Claim claim, Integer number) {
888	        audit(sheetId, user, event, person, claim, number, "");
889	    }
890	
891	    /** As above, with {@code suffix} (fields a later change added) at the end of the line. */
892	    private void audit(String sheetId, String user, String event, Person person, Claim claim, Integer number,
893	            String suffix) {
894	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
895	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
896	                + (number != null ? " number=" + number : "") + suffix);
897	    }
898	
899	    /** Refuse a clerk settling a claim whose due is above the sheet's clerk limit; a steward settles any. */
900	    private void requireMaySettle(Sheet sheet, String user, Person person, Claim claim) {
901	        BigDecimal limit = sheet.getClerkLimit();
902	        if (limit == null || settings.roleOf(sheet.getId(), user) == Role.STEWARD) {
903	            return;
904	        }
905	        BigDecimal due = figure(sheet.getId(), person, claim);
906	        if (due == null || due.compareTo(limit) > 0) {
907	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
908	                    "A clerk cannot settle a claim whose due is above the clerk limit");
909	        }
910	    }
911	
912	    /** Refuse a claim dated after the person's retirement. */
913	    private static void requireNotRetired(Person person, LocalDate date) {
914	        if (person.retiredOn(date)) {
915	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated after the person retired");
916	        }
917	    }
918	
919	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
920	        return date != null ? date : sheets.today(sheetId);
921	    }
922	
923	    private static String noteOf(String note) {
924	        return note == null ? "" : note.trim();
925	    }
926	}
927	-- The sheet's floor: a claim's live due is at least this (two decimals). It starts at 1.00.
928	ALTER TABLE sheet ADD COLUMN floor DECIMAL(15, 2) DEFAULT 1.00 NOT NULL;
929	-- The sheet's terms: a claim is due by its date plus this many days. It starts at 14.
930	ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
931	-- A settled claim's due, fixed when it is settled: its amount times its person's grade's rate then,
932	-- rounded half up to cents. Later changes to rates (or grades) do not alter it. Open and other
933	-- claims have none (their due stays live), as does one settled while its grade had no rate.
934	ALTER TABLE claim ADD COLUMN due DECIMAL(15, 2);
935	UPDATE claim c SET due = (
936	    SELECT ROUND(c.amount * r.pct / 100, 2) FROM person p JOIN rate r
937	        ON r.sheet_id = p.sheet_id AND r.grade = p.grade
938	    WHERE p.id = c.person_id)
939	WHERE c.status = 'SETTLED';
940	-- A statement taken for a person: the sheet's today when it was taken, their due-total then (null:
941	-- n/a) and how many of their claims counted. A person's statements are listed in the order taken (id).
942	CREATE TABLE statement (
943	    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
944	    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
945	    person_id BIGINT         NOT NULL REFERENCES person (id),
946	    taken_on  DATE           NOT NULL,
947	    due_total DECIMAL(15, 2),
948	    claims    INT            NOT NULL,
949	    taken_by  VARCHAR(200)   NOT NULL
950	);
951	CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
952	-- A claim bound by its person's last statement shows and totals the figure it had then (stated_due,
953	-- null: n/a) until the next statement rebinds or unbinds it.
954	ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
955	ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
