package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import net.officefloor.hq.app.session.SessionController;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets")
public class SheetController {

    public record SheetView(String id, LocalDate today) {
        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday());
        }
    }

    public record TodayChange(@NotNull LocalDate today) {}

    private final SheetService service;

    public SheetController(SheetService service) {
        this.service = service;
    }

    /** Load a sheet by id, starting it empty when it was never loaded before. */
    @PostMapping("/{id}/load")
    public SheetView load(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String id,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user) {
        return SheetView.of(service.load(id, user));
    }

    /** Change the sheet's "today". */
    @PutMapping("/{id}/today")
    public SheetView setToday(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String id,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @Valid @RequestBody TodayChange change) {
        return SheetView.of(service.setToday(id, user, change.today()));
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;

/** A sheet: the unit everything else in the app is kept under. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's "today": every date-dependent decision in the sheet uses it, never the clock. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last claim number the sheet gave out; the next opened claim gets one more. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** A clerk may settle a claim only when its due is at or below this; none: no limit. */
    @Column(name = "clerk_limit", precision = 15, scale = 2)
    private BigDecimal clerkLimit;

    /** A claim's live due is at least this; a fixed, bound or closed-period figure is not changed by it. */
    @Column(name = "floor", nullable = false, precision = 15, scale = 2)
    private BigDecimal floor = new BigDecimal("1.00");

    /** A claim is due by its date plus this many days. */
    @Column(name = "terms", nullable = false)
    private int terms = 14;

    protected Sheet() {}

    public Sheet(String id, String createdBy, Instant createdAt, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.createdAt = createdAt;
        this.today = today;
    }

    public String getId() { return id; }

    public String getCreatedBy() { return createdBy; }

    public Instant getCreatedAt() { return createdAt; }

    public LocalDate getToday() { return today; }

    public void setToday(LocalDate today) { this.today = today; }

    public BigDecimal getClerkLimit() { return clerkLimit; }

    public void setClerkLimit(BigDecimal clerkLimit) { this.clerkLimit = clerkLimit; }

    public BigDecimal getFloor() { return floor; }

    public void setFloor(BigDecimal floor) { this.floor = floor; }

    public int getTerms() { return terms; }

    public void setTerms(int terms) { this.terms = terms; }

    /** Give out the sheet's next claim number. */
    public int takeClaimNumber() { return ++lastClaimNumber; }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.LockModeType;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** The sheet, locked until the transaction ends so changes to it are made one at a time. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from Sheet s where s.id = :id")
    Optional<Sheet> findByIdForUpdate(String id);
}
package net.officefloor.hq.app.sheet;

import java.time.Instant;
import java.time.LocalDate;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollups;

    public SheetService(SheetRepository sheets, RollupService rollups) {
        this.sheets = sheets;
        this.rollups = rollups;
    }

    /** The sheet with this id; a sheet never loaded before is started empty, today at the real date. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
            } catch (DataIntegrityViolationException raced) {
                return sheets.findById(id).orElseThrow(() -> raced);
            }
        });
    }

    /**
     * The sheet's "today". Every decision that depends on the date, and every default date, uses
     * this and never the real clock.
     */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
    }

    /**
     * Change the sheet's "today" (the sheet is started when it was never loaded before). It has no
     * audit line of its own, but is followed by the rollup lines of the figures it moves.
     */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = lock(id, user);
        RollupService.Rollup before = rollups.snapshot(id);
        sheet.setToday(today);
        sheets.flush();
        rollups.recordChanges(id, user, before);
        return sheet;
    }

    /**
     * Lock the sheet until the current transaction ends, so its claims' statuses change one at a
     * time (the sheet is started when it was never loaded before).
     */
    @Transactional
    public Sheet lock(String id, String user) {
        return sheets.findByIdForUpdate(id).orElseGet(() -> {
            load(id, user);
            return sheets.findByIdForUpdate(id).orElseThrow();
        });
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The sheet's settings (its clerk limit, floor and terms) and the roles it gives user names. */
@Service
public class SettingsService {

    private final SheetRoleRepository roles;
    private final SheetService sheets;
    private final RollupService rollups;
    private final Audit audit;

    public SettingsService(SheetRoleRepository roles, SheetService sheets, RollupService rollups, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's settings now. */
    @Transactional
    public Sheet settings(String sheetId, String user) {
        return sheets.load(sheetId, user);
    }

    /**
     * Save the settings given: {@code setClerkLimit} the clerk limit (null: no limit), a non-null
     * {@code floor} the floor, a non-null {@code terms} the terms in days; each one saved is audited, even when its value is the same. A floor
     * that moves live dues records the rollups that moved.
     */
    @Transactional
    public Sheet save(String sheetId, String user, boolean setClerkLimit, BigDecimal clerkLimit, BigDecimal floor,
            Integer terms) {
        Sheet sheet = sheets.lock(sheetId, user);
        if (setClerkLimit) {
            sheet.setClerkLimit(clerkLimit);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=clerk-limit value=" + (clerkLimit == null ? "" : clerkLimit.toPlainString()));
        }
        if (floor != null) {
            RollupService.Rollup before = rollups.snapshot(sheetId);
            sheet.setFloor(floor);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=floor value=" + floor.toPlainString());
            rollups.recordChanges(sheetId, user, before);
        }
        if (terms != null) {
            sheet.setTerms(terms);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=terms value=" + terms);
        }
        return sheet;
    }

    /** The roles the sheet gives user names, by name; a name not among them is a clerk. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** The role the sheet gives a user name; clerk when it gives none. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** Give a user name a role, replacing the one it had. */
    @Transactional
    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
        sheets.lock(sheetId, user);
        SheetRole entry = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new SheetRole(sheetId, userName, role));
        entry.setRole(role);
        SheetRole saved = roles.saveAndFlush(entry);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
                + " user=" + userName + " role=" + role.name().toLowerCase());
        return saved;
    }
}
package net.officefloor.hq.app.settings;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.session.SessionController;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class SettingsController {

    /**
     * The sheet's settings, as text with two decimals: the clerk limit (null when there is none) and
     * the floor; and the terms in days.
     */
    public record SettingsView(String clerkLimit, String floor, int terms) {
        static SettingsView of(Sheet sheet) {
            BigDecimal limit = sheet.getClerkLimit();
            return new SettingsView(limit == null ? null : limit.setScale(2).toPlainString(),
                    sheet.getFloor().setScale(2).toPlainString(), sheet.getTerms());
        }
    }

    /**
     * The settings to save; a setting left out (null) is not changed. The clerk limit is 0.00 or more
     * with up to two decimals, blank for no limit; the floor is 0.00 or more with up to two decimals; the terms are a whole number of days, 0 or more.
     */
    public record SettingsForm(
            @Pattern(regexp = "\\s*|\\d{1,13}(\\.\\d{1,2})?") String clerkLimit,
            @Pattern(regexp = "\\d{1,13}(\\.\\d{1,2})?") String floor,
            @Pattern(regexp = "\\d{1,4}") String terms) {

        BigDecimal clerkLimitValue() {
            return clerkLimit == null || clerkLimit.isBlank() ? null : new BigDecimal(clerkLimit).setScale(2);
        }

        BigDecimal floorValue() {
            return floor == null ? null : new BigDecimal(floor).setScale(2);
        }

        Integer termsValue() {
            return terms == null ? null : Integer.valueOf(terms);
        }
    }

    /** A user name's role, in lower case (clerk or steward). */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole role) {
            return new RoleView(role.getUserName(), role.getRole().name().toLowerCase());
        }
    }

    public record RoleForm(
            @NotBlank @Size(max = 100) String user,
            @NotNull @Pattern(regexp = "clerk|steward") String role) {

        Role roleValue() {
            return Role.valueOf(role.toUpperCase());
        }
    }

    private final SettingsService service;

    public SettingsController(SettingsService service) {
        this.service = service;
    }

    @GetMapping("/settings")
    public SettingsView settings(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user) {
        return SettingsView.of(service.settings(sheetId, user));
    }

    /** Save the sheet's settings given; one left out keeps its value. */
    @PutMapping("/settings")
    public SettingsView save(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @Valid @RequestBody SettingsForm form) {
        return SettingsView.of(service.save(sheetId, user, form.clerkLimit() != null, form.clerkLimitValue(),
                form.floorValue(), form.termsValue()));
    }

    /** The roles the sheet gives user names, by name. */
    @GetMapping("/roles")
    public List<RoleView> roles(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user) {
        return service.roles(sheetId).stream().map(RoleView::of).toList();
    }

    /** Give a user name a role (clerk or steward); any other role is refused (400). */
    @PutMapping("/roles")
    public RoleView setRole(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @Valid @RequestBody RoleForm form) {
        return RoleView.of(service.setRole(sheetId, user, form.user().trim(), form.roleValue()));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
 * claimed-total and due-total. A change takes a snapshot before it and, once its own audit lines are
 * written, records a ROLLUP line per person whose figures moved and a TOTALS line when the totals did.
 */
@Service
public class RollupService {

    /** A person's figures, as text with two decimals; the due-total is "n/a" when they have none. */
    public record Figures(String name, String claimed, String dueTotal) {}

    /** Each person's figures by id, in the order they were added, and the sheet's totals. */
    public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /**
     * The sheet's figures now. Only open and settled claims count (a held person's open ones do not); a person's due-total is the sum of
     * their figures (those with one), n/a when their grade has no rate in force on the sheet's today
     * and no counting claim of theirs keeps a fixed (settled or stated) figure.
     */
    @Transactional(readOnly = true)
    public Rollup snapshot(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElseGet(LocalDate::now);
        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> c.getStatus().counts())
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, Figures> out = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counted = byPerson.getOrDefault(p.getId(), List.of()).stream()
                    .filter(c -> counts(p, c))
                    .toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            for (Claim c : counted) {
                claimed = claimed.add(c.getAmount());
                BigDecimal figure = figure(sheetId, p, c);
                if (figure != null) due = due.add(figure);
            }
            boolean rated = rates.findInForce(sheetId, p.getGrade(), today).isPresent();
            boolean anyFixed = counted.stream().anyMatch(Claim::keepsFigure);
            claimedTotal = claimedTotal.add(claimed);
            if (rated || anyFixed) dueTotal = dueTotal.add(due);
            out.put(p.getId(), new Figures(p.getName(), text(claimed), rated || anyFixed ? text(due) : "n/a"));
        }
        return new Rollup(out, text(claimedTotal), text(dueTotal));
    }

    /**
     * Whether a claim counts in the live totals: open and settled claims do, except the open claims
     * of a person on hold.
     */
    public static boolean counts(Person person, Claim claim) {
        return claim.getStatus().counts() && !(person.isHeld() && claim.getStatus() == ClaimStatus.OPEN);
    }

    /**
     * Record, once the change commits, a ROLLUP line for each person whose figures moved since
     * {@code before} (a person who did not exist then counts as moved), then a TOTALS line when the
     * sheet's totals moved.
     */
    @Transactional(readOnly = true)
    public void recordChanges(String sheetId, String user, Rollup before) {
        Rollup after = snapshot(sheetId);
        List<String> lines = new ArrayList<>();
        after.people().forEach((id, now) -> {
            Figures was = before.people().get(id);
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
                lines.add("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal());
            }
        });
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
            lines.add("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal());
        }
        lines.forEach(audit::recordOnCommit);
    }

    /**
     * The figure a claim shows: a settled claim's fixed due, else the figure its person's last
     * statement bound it to, else its amount times the rate in force on its date, raised to the
     * sheet's floor; null when none.
     */
    @Transactional(readOnly = true)
    public BigDecimal figure(String sheetId, Person person, Claim claim) {
        if (claim.getDue() != null) return claim.getDue();
        if (claim.isStated()) return claim.getStatedDue();
        BigDecimal floor = sheets.findById(sheetId).map(Sheet::getFloor).orElse(BigDecimal.ZERO);
        return rates.findInForce(sheetId, person.getGrade(), claim.getDate())
                .map(rate -> due(claim.getAmount(), rate).max(floor).setScale(2))
                .orElse(null);
    }

    /** The amount times the rate's percent, rounded half to even to cents (as the screen works it out). */
    private static BigDecimal due(BigDecimal amount, Rate rate) {
        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }

    private static String text(BigDecimal amount) {
        return amount.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim a person on a sheet makes. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** Given when the claim is opened; none while a draft; a voided claim keeps it (never reused). */
    @Column(name = "number")
    private Integer number;

    /** The user who opened the claim; none while a draft. They may not settle it. */
    @Column(name = "opened_by")
    private String openedBy;

    /** Fixed when the claim is settled; none while live, or when its grade had no rate then (it stays live). */
    @Column(name = "due", precision = 15, scale = 2)
    private BigDecimal due;

    /** Bound by its person's last statement: it shows and totals {@code statedDue} until the next one. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the claim had at its person's last statement, when bound; none when it was n/a. */
    @Column(name = "stated_due", precision = 15, scale = 2)
    private BigDecimal statedDue;

    protected Claim() {}

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public Long getPersonId() { return personId; }

    public BigDecimal getAmount() { return amount; }

    public void setAmount(BigDecimal amount) { this.amount = amount; }

    public LocalDate getDate() { return date; }

    public void setDate(LocalDate date) { this.date = date; }

    public String getNote() { return note; }

    public void setNote(String note) { this.note = note; }

    public ClaimStatus getStatus() { return status; }

    public void setStatus(ClaimStatus status) { this.status = status; }

    public Integer getNumber() { return number; }

    public void setNumber(Integer number) { this.number = number; }

    public String getOpenedBy() { return openedBy; }

    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }

    public BigDecimal getDue() { return due; }

    public void setDue(BigDecimal due) { this.due = due; }

    public boolean isStated() { return stated; }

    public BigDecimal getStatedDue() { return statedDue; }

    /** Whether the claim keeps a figure that does not follow the rates: a settled due, or a bound one (not n/a). */
    public boolean keepsFigure() {
        return due != null || (stated && statedDue != null);
    }

    /** Bind the claim to this figure (null: n/a). */
    public void bind(BigDecimal figure) {
        this.stated = true;
        this.statedDue = figure;
    }

    /** Leave the claim unbound: its figure is live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.Statement;
import net.officefloor.hq.app.person.StatementRepository;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final StatementRepository statements;
    private final SheetService sheets;
    private final RollupService rollups;
    private final PeriodService periods;
    private final SettingsService settings;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates,
            StatementRepository statements, SheetService sheets, RollupService rollups, PeriodService periods,
            SettingsService settings, Audit audit) {
        this.periods = periods;
        this.settings = settings;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.statements = statements;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByIdDesc(sheetId);
    }

    /**
     * Add a claim for a person; without a date it is dated the sheet's today. One dated in a closed
     * period is refused.
     */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
        sheets.lock(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate dated = dateOrToday(sheetId, date);
        periods.requireOpenOn(sheetId, dated);
        requireNotRetired(person, dated);
        RollupService.Rollup before = rollups.snapshot(sheetId);
        Claim saved = claims.saveAndFlush(new Claim(sheetId, personId, amount, dated, noteOf(note)));
        audit(sheetId, user, "CLAIM_ADDED", person, saved, saved.getNumber());
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Change a draft claim's amount, date and note; without a date it is dated the sheet's today. A
     * claim that is no longer a draft is refused (an open one is voided and a new one added instead),
     * as is one dated in a closed period, or moved into one.
     */
    @Transactional
    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note) {
        sheets.lock(sheetId, user);
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited");
        }
        LocalDate dated = dateOrToday(sheetId, date);
        periods.requireOpenOn(sheetId, claim.getDate());
        periods.requireOpenOn(sheetId, dated);
        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        requireNotRetired(owner, dated);
        RollupService.Rollup before = rollups.snapshot(sheetId);
        claim.setAmount(amount);
        claim.setDate(dated);
        claim.setNote(noteOf(note));
        Claim saved = claims.saveAndFlush(claim);
        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        audit(sheetId, user, "CLAIM_EDITED", person, saved, saved.getNumber());
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Move a claim to its next status; a change its current status does not allow is refused, as is
     * settling it by the user who opened it, settling it by a clerk when its due is above the sheet's
     * clerk limit (or it has none while there is a limit), and any change to a claim dated in a closed
     * period.
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
        Sheet sheet = sheets.lock(sheetId, user);
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        periods.requireOpenOn(sheetId, claim.getDate());
        if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next);
        }
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (next == ClaimStatus.SETTLED) {
            requireMaySettle(sheet, user, person, claim);
        }
        RollupService.Rollup before = rollups.snapshot(sheetId);
        Integer number = next == ClaimStatus.OPEN ? Integer.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
        claim.setStatus(next);
        claim.setNumber(number);
        if (next == ClaimStatus.OPEN) {
            claim.setOpenedBy(user);
        }
        if (next == ClaimStatus.SETTLED) {
            claim.setDue(figure(sheetId, person, claim));
        }
        Claim saved = claims.saveAndFlush(claim);
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            default -> "CLAIM_VOIDED";
        };
        String suffix = next == ClaimStatus.SETTLED
                ? " due=" + (saved.getDue() == null ? "n/a" : saved.getDue().setScale(2).toPlainString())
                : "";
        audit(sheetId, user, event, person, saved, number, suffix);
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Take a statement for a person on the sheet's today: their due-total then (the sum of the figures
     * of their claims that count, a held person's open ones not among them; n/a when their grade has
     * no rate in force today and none of those claims has a fixed or bound figure) is recorded, and each claim that counts is bound to its
     * figure then, the others left unbound. Their claims, newest first.
     */
    @Transactional
    public List<Claim> statement(String sheetId, String user, long personId) {
        Sheet sheet = sheets.lock(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        RollupService.Rollup before = rollups.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> c.getPersonId().equals(personId))
                .toList();
        List<Claim> counting = theirs.stream().filter(c -> RollupService.counts(person, c)).toList();
        boolean anyFixed = counting.stream().anyMatch(Claim::keepsFigure);
        boolean rated = rates.findInForce(sheetId, person.getGrade(), sheet.getToday()).isPresent();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : theirs) {
            if (RollupService.counts(person, c)) {
                BigDecimal figure = figure(sheetId, person, c);
                if (figure != null) total = total.add(figure);
                c.bind(figure);
            } else {
                c.unbind();
            }
        }
        claims.saveAllAndFlush(theirs);
        BigDecimal dueTotal = rated || anyFixed ? total : null;
        statements.saveAndFlush(new Statement(sheetId, personId, sheet.getToday(), dueTotal, counting.size(), user));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString())
                + " claims=" + counting.size());
        rollups.recordChanges(sheetId, user, before);
        return theirs;
    }

    /** The figure a claim shows (see {@link RollupService#figure}); null when none. */
    private BigDecimal figure(String sheetId, Person person, Claim claim) {
        return rollups.figure(sheetId, person, claim);
    }

    /**
     * Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd; a claim
     * with a number (a voided one keeps it) ends with it.
     */
    private void audit(String sheetId, String user, String event, Person person, Claim claim, Integer number) {
        audit(sheetId, user, event, person, claim, number, "");
    }

    /** As above, with {@code suffix} (fields a later change added) at the end of the line. */
    private void audit(String sheetId, String user, String event, Person person, Claim claim, Integer number,
            String suffix) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number != null ? " number=" + number : "") + suffix);
    }

    /** Refuse a clerk settling a claim whose due is above the sheet's clerk limit; a steward settles any. */
    private void requireMaySettle(Sheet sheet, String user, Person person, Claim claim) {
        BigDecimal limit = sheet.getClerkLimit();
        if (limit == null || settings.roleOf(sheet.getId(), user) == Role.STEWARD) {
            return;
        }
        BigDecimal due = figure(sheet.getId(), person, claim);
        if (due == null || due.compareTo(limit) > 0) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "A clerk cannot settle a claim whose due is above the clerk limit");
        }
    }

    /** Refuse a claim dated after the person's retirement. */
    private static void requireNotRetired(Person person, LocalDate date) {
        if (person.retiredOn(date)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated after the person retired");
        }
    }

    private LocalDate dateOrToday(String sheetId, LocalDate date) {
        return date != null ? date : sheets.today(sheetId);
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }
}
-- The sheet's floor: a claim's live due is at least this (two decimals). It starts at 1.00.
ALTER TABLE sheet ADD COLUMN floor DECIMAL(15, 2) DEFAULT 1.00 NOT NULL;
-- The sheet's terms: a claim is due by its date plus this many days. It starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- A settled claim's due, fixed when it is settled: its amount times its person's grade's rate then,
-- rounded half up to cents. Later changes to rates (or grades) do not alter it. Open and other
-- claims have none (their due stays live), as does one settled while its grade had no rate.
ALTER TABLE claim ADD COLUMN due DECIMAL(15, 2);
UPDATE claim c SET due = (
    SELECT ROUND(c.amount * r.pct / 100, 2) FROM person p JOIN rate r
        ON r.sheet_id = p.sheet_id AND r.grade = p.grade
    WHERE p.id = c.person_id)
WHERE c.status = 'SETTLED';
-- A statement taken for a person: the sheet's today when it was taken, their due-total then (null:
-- n/a) and how many of their claims counted. A person's statements are listed in the order taken (id).
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    taken_on  DATE           NOT NULL,
    due_total DECIMAL(15, 2),
    claims    INT            NOT NULL,
    taken_by  VARCHAR(200)   NOT NULL
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
-- A claim bound by its person's last statement shows and totals the figure it had then (stated_due,
-- null: n/a) until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);

