9	export interface Claim {
10	  id: number;
11	  personId: number;
12	  /** Text with two decimals, e.g. "10.00". */
13	  amount: string;
14	  /** yyyy-MM-dd */
15	  date: string;
16	  note: string;
17	  status: ClaimStatus;
18	  /** Given when opened; null while a draft and once voided. */
19	  number: number | null;
20	  /** A settled claim's due, fixed when it was settled, as text with two decimals; null while live, or when its grade had no rate then (it then follows the rates). */
21	  due: string | null;
22	  /** The user who opened it; null while a draft. They may not settle it. */
23	  openedBy: string | null;
24	  /** Bound by its person's last statement: it shows and totals `statedDue` until the next one. */
25	  stated: boolean;
26	  /** The figure it had at that statement, as text with two decimals; null when it had none (n/a). */
27	  statedDue: string | null;
28	}
29	
30	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
31	
32	/** A change of status a claim's buttons ask for. */
33	export type ClaimAction = 'open' | 'settle' | 'void';
34	
35	/** Only open and settled claims count toward claimed and due; drafts and voided claims do not. */
36	export function counts(c: Claim): boolean {
37	  return c.status === 'OPEN' || c.status === 'SETTLED';
38	}
39	
40	/** A claim keeps a figure that does not follow the rates: settled with a fixed due, or bound by a statement to one (not n/a). */
41	export function fixed(c: Claim): boolean {
42	  return c.due !== null || (c.stated && c.statedDue !== null);
43	}
44	
45	/**
46	 * A claim's due in cents: a settled claim's fixed figure, else the figure its person's last statement
47	 * bound it to, otherwise its amount times the rate in force on its date (looked up by `rateOn`, in
48	 * hundredths of a percent), raised to the sheet's floor (in cents); undefined when it has none.
49	 */
50	export function claimDue(c: Claim, rateOn: (date: string) => number | undefined, floor: number): number | undefined {
51	  if (c.due !== null) return cents(c.due);
52	  if (c.stated) return c.statedDue === null ? undefined : cents(c.statedDue);
53	  const rate = rateOn(c.date);
54	  return rate === undefined ? undefined : Math.max(due(cents(c.amount), rate), floor);
55	}
56	
57	/** The date (yyyy-MM-dd) a claim is due by: its date plus the terms (days). */
58	export function dueBy(c: Claim, terms: number): string {
59	  const [y, m, d] = c.date.split('-').map(Number);
60	  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
61	}
62	
63	/** A claim is overdue when it is open and its due-by is before the sheet's today (yyyy-MM-dd; null: none loaded). */
64	export function overdue(c: Claim, terms: number, today: string | null): boolean {
65	  return today !== null && c.status === 'OPEN' && dueBy(c, terms) < today;
66	}
