75	// The active sheet's claims, newest first, and what they add up to (kept in cents so sums are exact).
76	@Injectable({ providedIn: 'root' })
77	export class ClaimsService {
78	  private readonly http = inject(HttpClient);
79	  private readonly session = inject(SessionService);
80	  private readonly sheets = inject(SheetService);
81	  private readonly people = inject(PeopleService);
82	  private readonly list = signal<Claim[]>([]);
83	
84	  readonly claims = this.list.asReadonly();
85	
86	  /** The ids of the people on hold. */
87	  private readonly heldIds = computed(
88	    () => new Set(this.people.people().filter((p) => p.held).map((p) => p.id)),
89	  );
90	
91	  /** Whether a claim counts in the live totals: open and settled ones do, except a held person's open ones. */
92	  readonly live = computed(() => {
93	    const held = this.heldIds();
94	    return (c: Claim) => counts(c) && !(c.status === 'OPEN' && held.has(c.personId));
95	  });
96	
97	  /** Each person's claims, newest first. */
98	  readonly byPerson = computed(() => {
99	    const out = new Map<number, Claim[]>();
100	    for (const c of this.list()) out.set(c.personId, [...(out.get(c.personId) ?? []), c]);
101	    return out;
102	  });
103	
104	  /** Each person's claimed (live claims), in cents. */
105	  readonly claimedCents = computed(() => {
106	    const out = new Map<number, number>();
107	    for (const c of this.list().filter(this.live())) out.set(c.personId, (out.get(c.personId) ?? 0) + cents(c.amount));
108	    return out;
109	  });
110	
111	  /** Everyone's claimed (live claims) added up, in cents. */
112	  readonly totalCents = computed(() => this.list().filter(this.live()).reduce((sum, c) => sum + cents(c.amount), 0));
113	
114	  /** Re-read the active sheet's claims from the store. */
115	  reload(): Observable<unknown> {
116	    const id = this.sheets.sheetId();
117	    if (!id) {
118	      this.list.set([]);
119	      return of(null);
120	    }
121	    return this.http
122	      .get<Claim[]>(this.url(id), { headers: this.session.headers() })
123	      .pipe(tap((claims) => {
124	        if (this.sheets.sheetId() === id) this.list.set(claims);
125	      }));
126	  }
127	
128	  add(personId: number, form: ClaimForm): Observable<Claim> {
129	    const sheet = this.sheet();
130	    return this.http
131	      .post<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/people/${personId}/claims`, form, {
132	        headers: this.session.headers(),
133	      })
134	      .pipe(tap((c) => this.list.update((all) => [c, ...all])));
135	  }
136	
137	  /**
138	   * Add a draft claim of this amount, dated the sheet's today, for the person with this name; one
139	   * not on the sheet is added first with grade A. The caller re-reads the people.
140	   */
141	  quickAdd(name: string, amount: string): Observable<Claim> {
142	    const sheet = this.sheet();
143	    return this.http
144	      .post<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/quick-add`, { name, amount }, {
145	        headers: this.session.headers(),
146	      })
147	      .pipe(tap((c) => this.list.update((all) => [c, ...all])));
148	  }
149	
150	  /** Take a statement for a person, binding their counting claims; the caller re-reads the people. */
151	  statement(personId: number): Observable<Claim[]> {
152	    const sheet = this.sheet();
153	    return this.http
154	      .post<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/people/${personId}/statement`, null, {
155	        headers: this.session.headers(),
156	      })
157	      .pipe(tap((theirs) => {
158	        const byId = new Map(theirs.map((c) => [c.id, c]));
159	        this.list.update((all) => all.map((o) => byId.get(o.id) ?? o));
160	      }));
161	  }
162	
163	  edit(claimId: number, form: ClaimForm): Observable<Claim> {
164	    return this.http
165	      .put<Claim>(`${this.url(this.sheet())}/${claimId}`, form, { headers: this.session.headers() })
166	      .pipe(tap((c) => this.list.update((all) => all.map((o) => (o.id === c.id ? c : o)))));
167	  }
168	
169	  changeStatus(claimId: number, action: ClaimAction): Observable<Claim> {
170	    return this.http
171	      .post<Claim>(`${this.url(this.sheet())}/${claimId}/${action}`, null, { headers: this.session.headers() })
172	      .pipe(tap((c) => this.list.update((all) => all.map((o) => (o.id === c.id ? c : o)))));
173	  }
174	
175	  private sheet(): string {
176	    const id = this.sheets.sheetId();
177	    if (!id) throw new Error('no sheet loaded');
178	    return id;
179	  }
180	
181	  private url(sheetId: string): string {
182	    return `/api/sheets/${encodeURIComponent(sheetId)}/claims`;
183	  }
184	}
