186	/** "12.34" as 1234. */
187	export function cents(amount: string): number {
188	  const [whole, frac = ''] = amount.split('.');
189	  return Number(whole) * 100 + Number((frac + '00').slice(0, 2));
190	}
191	
192	/** 1234 as "12.34". */
193	export function money(cents: number): string {
194	  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
195	}
