228	/** The floor a sheet starts with. */
229	const DEFAULT_FLOOR = '1.00';
230	
231	/** The terms (days) a sheet starts with. */
232	const DEFAULT_TERMS = 14;
233	
234	// The active sheet's settings and the roles it gives user names. A name with no role is a clerk; a
235	// clerk may settle a claim only when its due is at or below the clerk limit (none: no limit), a
236	// steward any claim. A claim's live due is at least the floor; it is due by its date plus the terms.
237	@Injectable({ providedIn: 'root' })
238	export class SettingsService {
239	  private readonly http = inject(HttpClient);
240	  private readonly session = inject(SessionService);
241	  private readonly sheets = inject(SheetService);
242	  private readonly limit = signal<string | null>(null);
243	  private readonly floorValue = signal<string>(DEFAULT_FLOOR);
244	  private readonly termsValue = signal<number>(DEFAULT_TERMS);
245	  private readonly list = signal<RoleEntry[]>([]);
246	
247	  readonly clerkLimit = this.limit.asReadonly();
248	  readonly floor = this.floorValue.asReadonly();
249	  /** The floor in cents. */
250	  readonly floorCents = computed(() => cents(this.floorValue()));
251	  /** The terms in days. */
252	  readonly terms = this.termsValue.asReadonly();
253	  readonly roles = this.list.asReadonly();
254	
255	  /** Re-read the active sheet's settings and roles from the store. */
256	  reload(): Observable<unknown> {
257	    const id = this.sheets.sheetId();
258	    if (!id) {
259	      this.limit.set(null);
260	      this.floorValue.set(DEFAULT_FLOOR);
261	      this.termsValue.set(DEFAULT_TERMS);
262	      this.list.set([]);
263	      return of(null);
264	    }
265	    const headers = this.session.headers();
266	    return forkJoin([
267	      this.http.get<SettingsView>(`${this.url(id)}/settings`, { headers }),
268	      this.http.get<RoleEntry[]>(`${this.url(id)}/roles`, { headers }),
269	    ]).pipe(tap(([settings, roles]) => {
270	      if (this.sheets.sheetId() !== id) return;
271	      this.set(settings);
272	      this.list.set(roles);
273	    }));
274	  }
275	
276	  /** Save the settings given (the others keep their values). */
277	  save(change: SettingsChange): Observable<SettingsView> {
278	    const id = this.sheets.sheetId();
279	    if (!id) throw new Error('no sheet loaded');
280	    return this.http
281	      .put<SettingsView>(`${this.url(id)}/settings`, change, { headers: this.session.headers() })
282	      .pipe(tap((s) => this.set(s)));
283	  }
284	
285	  private set(settings: SettingsView): void {
286	    this.limit.set(settings.clerkLimit);
287	    this.floorValue.set(settings.floor);
288	    this.termsValue.set(settings.terms);
289	  }
290	
291	  /** Give a user name a role, replacing the one it had; refused for any role but clerk or steward. */
292	  setRole(user: string, role: string): Observable<RoleEntry> {
293	    const id = this.sheets.sheetId();
294	    if (!id) throw new Error('no sheet loaded');
295	    return this.http
296	      .put<RoleEntry>(`${this.url(id)}/roles`, { user, role }, { headers: this.session.headers() })
297	      .pipe(tap((r) => this.list.update((all) => [...all.filter((o) => o.user !== r.user), r]
298	        .sort((a, b) => a.user.localeCompare(b.user)))));
299	  }
300	
301	  private url(sheetId: string): string {
302	    return `/api/sheets/${encodeURIComponent(sheetId)}`;
303	  }
304	}
