363	export class Settings {
364	  protected readonly settings = inject(SettingsService);
365	  private readonly sheets = inject(SheetService);
366	  protected readonly roles = ROLES;
367	  protected readonly settingsForm = new FormGroup({
368	    clerkLimit: new FormControl('', { nonNullable: true }),
369	    floor: new FormControl('', { nonNullable: true }),
370	    terms: new FormControl('', { nonNullable: true }),
371	  });
372	  protected readonly roleForm = new FormGroup({
373	    user: new FormControl('', { nonNullable: true }),
374	    role: new FormControl('', { nonNullable: true }),
375	  });
376	  protected readonly settingsError = signal('');
377	  protected readonly roleError = signal('');
378	  /** A submit is waiting for its answer; another submit of the same form meanwhile is ignored. */
379	  private savingSettings = false;
380	  private savingRole = false;
381	
382	  constructor() {
383	    this.settingsForm.valueChanges.subscribe(() => this.settingsError.set(''));
384	    this.roleForm.valueChanges.subscribe(() => this.roleError.set(''));
385	    effect(() => {
386	      this.sheets.loads();
387	      untracked(() => {
388	        this.settingsError.set('');
389	        this.roleError.set('');
390	        this.resetSettings();
391	        this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
392	      });
393	    });
394	  }
395	
396	  protected save(): void {
397	    if (this.savingSettings) return;
398	    this.settingsError.set('');
399	    const { clerkLimit, floor, terms } = this.settingsForm.controls;
400	    const limit = clerkLimit.value.trim();
401	    const least = floor.value.trim();
402	    const days = terms.value.trim();
403	    if (limit !== '' && !/^\d{1,13}(\.\d{1,2})?$/.test(limit)) {
404	      this.settingsError.set('Enter a clerk limit of 0.00 or more with up to two decimals, or leave it empty.');
405	      return;
406	    }
407	    if (!/^\d{1,13}(\.\d{1,2})?$/.test(least)) {
408	      this.settingsError.set('Enter a floor of 0.00 or more with up to two decimals.');
409	      return;
410	    }
411	    if (!/^\d{1,4}$/.test(days)) {
412	      this.settingsError.set('Enter terms of 0 or more whole days.');
413	      return;
414	    }
415	    // Only the settings the user changed are saved (and audited).
416	    const change: SettingsChange = {};
417	    if (clerkLimit.dirty) change.clerkLimit = limit;
418	    if (floor.dirty) change.floor = least;
419	    if (terms.dirty) change.terms = days;
420	    this.savingSettings = true;
421	    this.settings.save(change).pipe(finalize(() => (this.savingSettings = false))).subscribe({
422	      next: () => this.resetSettings(),
423	      error: () => this.settingsError.set('Could not save the settings.'),
424	    });
425	  }
426	
427	  private resetSettings(): void {
428	    this.settingsForm.reset(
429	      { clerkLimit: this.settings.clerkLimit() ?? '', floor: this.settings.floor(),
430	        terms: String(this.settings.terms()) },
431	      { emitEvent: false },
432	    );
433	  }
434	
435	  protected setRole(): void {
436	    if (this.savingRole) return;
437	    this.roleError.set('');
438	    const { user, role } = this.roleForm.getRawValue();
439	    const u = user.trim();
440	    const r = role.trim();
441	    if (!u) {
442	      this.roleError.set('Enter a user name.');
443	      return;
444	    }
445	    if (!(ROLES as readonly string[]).includes(r)) {
446	      this.roleError.set(`Enter a role: ${ROLES.join(' or ')}.`);
447	      return;
448	    }
449	    this.savingRole = true;
450	    this.settings.setRole(u, r).pipe(finalize(() => (this.savingRole = false))).subscribe({
451	      next: () => this.roleForm.reset({ user: '', role: '' }, { emitEvent: false }),
452	      error: () => this.roleError.set('Could not set that role.'),
453	    });
454	  }
455	}
